SELECT split_part('abc~@~def~@~ghi', '~@~', 2), split_part('abc,def,ghi,jkl', ',', -2), split_part('a,b', '', 1), split_part('a,b', ',', 5);
SELECT concat('abcde', 2, NULL, 22), concat_ws(',', 'abcde', 2, NULL, 22), concat(NULL), concat_ws(NULL, 'a');
SELECT replace('abcdefabcdef', 'cd', 'XX'), replace('abc', '', 'x'), strpos('high', 'ig'), position('om' in 'Thomas'), position('' in 'abc');
SELECT left('abcde', 2), left('abcde', -2), right('abcde', 2), right('abcde', -2), left('ab', 5);
SELECT lpad('hi', 5, 'xy'), rpad('hi', 5, 'xy'), lpad('hello', 3), rpad('hi', 4), lpad('hi', -1), lpad('hi', 5, '');
SELECT repeat('Pg', 4), repeat('x', 0), reverse('abcdé'), initcap('hi THOMAS'), initcap('a-b c_d 1e');
SELECT translate('12345', '143', 'ax'), chr(65), chr(233), ascii('x'), ascii(''), ascii('é');
SELECT md5('abc'), md5(''), starts_with('alphabet', 'alph'), starts_with('alphabet', 'beta');
SELECT overlay('Txxxxas' placing 'hom' from 2 for 4), overlay('Txxxxas' placing 'hom' from 2), substr('alphabet', 3, 2), substr('alphabet', 3);
SELECT format('Hello %s', 'World'), format('Testing %s, %s, %s, %%', 'one', 'two', 'three');
SELECT format('INSERT INTO %I VALUES(%L)', 'Foo bar', 'O''Reilly'), format('INSERT INTO %I VALUES(%L)', 'locations', 'C:\Program Files');
SELECT format('[%10s]', 'foo'), format('[%-10s]', 'foo'), format('%2$s %1$s', 'world', 'hello'), format('%s', NULL), format('%L', NULL);
SELECT quote_literal('it''s'), quote_literal(42), quote_nullable(NULL), quote_nullable('x');
SELECT regexp_match('foobarbequebaz', 'bar.*que'), regexp_match('foobarbequebaz', '(bar)(beque)'), regexp_match('foobarbequebaz', 'x');
SELECT regexp_match('abcd', 'a|ab'), regexp_match('XY1234Z', 'Y*([0-9]{1,3})'), regexp_match('XY1234Z', 'Y*?([0-9]{1,3})');
SELECT regexp_matches('foobarbequebazilbarfbonk', '(b[^b]+)(b[^b]+)', 'g');
SELECT regexp_matches('abc', 'x', 'g');
SELECT regexp_replace('Thomas', '.[mN]a.', 'M'), regexp_replace('foobarbaz', 'b(..)', 'X\1Y', 'g');
SELECT regexp_replace('A PostgreSQL function', 'a|e|i|o|u', 'X', 1, 0, 'i'), regexp_replace('A PostgreSQL function', 'a|e|i|o|u', 'X', 1, 3, 'i');
SELECT regexp_replace('abc', 'b', '[\&]'), regexp_replace('abc', '(b)', '\\'), regexp_replace('ABC', 'b', 'x', 'gi');
SELECT regexp_split_to_array('hello world', '\s+'), regexp_split_to_array('abc', ''), regexp_split_to_array('a,b,', ',');
SELECT foo FROM regexp_split_to_table('the quick brown fox jumps over the lazy dog', '\s+') AS foo;
SELECT regexp_split_to_table('the quick', '\s*');
SELECT regexp_count('ABCABCAXYaxy', 'A.'), regexp_count('ABCABCAXYaxy', 'A.', 1, 'i'), regexp_count('abc', '');
SELECT regexp_instr('number of your street, town zip, FR', '[^,]+', 1, 2), regexp_instr('ABCDEFGHI', '(c..)(...)', 1, 1, 0, 'i', 2);
SELECT regexp_substr('number of your street, town zip, FR', '[^,]+', 1, 2), regexp_substr('ABCDEFGHI', '(c..)(...)', 1, 1, 'i', 2);
SELECT regexp_like('Hello World', 'world$', 'i'), regexp_like('Hello World', 'world$');
SELECT substring('Thomas' from '...$'), substring('Thomas' from 'o(.)m'), substring('Thomas' from 'x');
SELECT substring('foobar' similar '%#"o_b#"%' escape '#'), substring('foobar' from '%#"o_b#"%' for '#'), substring('foobar' similar '#"o_b#"%' escape '#');
SELECT 'abc' SIMILAR TO 'abc', 'abc' SIMILAR TO 'a', 'abc' SIMILAR TO '%(b|d)%', 'abc' SIMILAR TO '(b|c)%';
SELECT '-abc-' SIMILAR TO '%\mabc\M%', 'xyz' SIMILAR TO '%\mabc\M%', 'abc' NOT SIMILAR TO 'a_c', 'a%c' SIMILAR TO 'a#%c' ESCAPE '#';
SELECT 'aa' ~ '(a)\1', 'ab' ~ '(a)\1', 'foobar' ~ 'foo(?=bar)', 'foobaz' ~ 'foo(?!bar)', 'barfoo' ~ '(?<=bar)foo';
SELECT 'a cat' ~ '\mcat\M', 'concat' ~ '\mcat', 'ABC' ~ '(?i)abc', 'a.c' ~ '***=a.c', 'abc' ~ '***=a.c';
SELECT make_date(2013, 7, 15), make_date(-44, 3, 15), make_time(8, 15, 23.5), make_timestamp(2013, 7, 15, 8, 15, 23.5);
SELECT make_interval(days => 10), make_interval(1, 2, 3, 4, 5, 6, 7.5), make_interval(hours => 1, mins => 30);
SELECT date_bin('15 minutes', TIMESTAMP '2020-02-11 15:44:17', TIMESTAMP '2001-01-01'), date_bin('15 minutes', TIMESTAMP '2020-02-11 15:44:17', TIMESTAMP '2001-01-01 00:02:30');
SELECT isfinite(date '2001-02-16'), isfinite(timestamp '2001-02-16 21:28:30'), isfinite(interval '4 hours');
SELECT TIMESTAMP '2001-02-16 20:38:40' AT TIME ZONE '+05', '2001-02-16 20:38:40+00'::timestamptz AT TIME ZONE 'UTC', TIMESTAMP '2001-02-16 20:38:40' AT TIME ZONE INTERVAL '-08:00';
SELECT to_char(TIMESTAMP '2002-04-20 17:31:12.66', 'HH12:MI:SS'), to_char(TIMESTAMP '2002-04-20 17:31:12.66', 'Day, DD  HH12:MI:SS'), to_char(TIMESTAMP '2002-04-20 17:31:12.66', 'FMDay, FMDD  HH12:MI:SS');
SELECT to_char(TIMESTAMP '2002-04-20 17:31:12.66', 'YYYY-MM-DD"T"HH24:MI:SS.MS'), to_char(TIMESTAMP '2002-04-20 17:31:12.66', 'Month MON mon Mon'), to_char(TIMESTAMP '2002-04-20 17:31:12.66', 'DDDth Q CC J IW WW D ID');
