SELECT to_char(-485, '999PR'), to_char(485, 'RN'), to_char(485, 'FMRN'), to_char(5.2, 'FMRN'), to_char(482, '999th'), to_char(485, '"Good number:"999');
SELECT to_char(485.8, '"Pre:"999" Post:" .999'), to_char(12, '99V999'), to_char(12.4, '99V999'), to_char(12.45, '99V9'), to_char(0.0004859, '9.99EEEE'), to_char(1234, '99');
SELECT to_char(interval '15 hours 2 minutes 12 seconds', 'HH24:MI:SS'), to_char(0, '999'), to_char(1234.5::double precision, '9999.9');
SELECT to_date('05 Dec 2000', 'DD Mon YYYY'), to_date('20001205', 'YYYYMMDD'), to_date('5 12 95', 'DD MM YY'), to_timestamp('05 Dec 2000', 'DD Mon YYYY');
SELECT to_timestamp('2011-12-18 11:38 PM', 'YYYY-MM-DD HH12:MI PM'), to_timestamp(1284352323), to_number('12,454.8-', '99G999D9S'), to_number('1,234', '9G999');
SELECT to_json('Fred said "Hi."'::text), row_to_json(row(1, 'foo')), json_build_array(1, 2, 'foo', 4, 5), json_build_object('foo', 1, 2, row_to_json(row(3, 'bar')));
SELECT jsonb_build_object('b', 1, 'a', 2), jsonb_build_array('x', NULL), to_jsonb(1.50), to_json(ARRAY[1, 2]), to_json(true), to_json(NULL::text);
SELECT to_json(TIMESTAMP '2014-05-28 12:22:35.614298'), to_json(DATE '2014-05-28'), to_json('2014-05-28 12:22:35.614298+00'::timestamptz);
SELECT key, value FROM json_each('{"a":"foo", "b":"bar"}') ORDER BY key;
SELECT * FROM jsonb_each_text('{"a":"foo", "b":"bar"}');
SELECT * FROM json_array_elements('[1,true, [2,false]]');
SELECT * FROM jsonb_array_elements_text('["foo", "bar", null]');
SELECT * FROM json_object_keys('{"f1":"abc","f2":{"f3":"a", "f4":"b"}}');
SELECT json_extract_path('{"f2":{"f3":1},"f4":{"f5":99,"f6":"foo"}}', 'f4', 'f6'), json_extract_path_text('{"f2":{"f3":1},"f4":{"f5":99,"f6":"foo"}}', 'f4', 'f6');
SELECT jsonb_extract_path('{"a": [10, {"b": 2}]}', 'a', '1', 'b'), jsonb_extract_path_text('{"a": [10, {"b": 2}]}', 'a', '0');
