SELECT jsonb_set('[{"f1":1,"f2":null},2,null,3]', '{0,f1}', '[2,3,4]', false), jsonb_set('[{"f1":1,"f2":null},2]', '{0,f3}', '[2,3,4]');
SELECT jsonb_insert('{"a": [0,1,2]}', '{a, 1}', '"new_value"'), jsonb_insert('{"a": [0,1,2]}', '{a, 1}', '"new_value"', true);
SELECT jsonb_pretty('[{"f1":1,"f2":null}, 2]');
SELECT '{"a":1, "b":2}'::jsonb ? 'b', '["a", "b", "c"]'::jsonb ? 'b', '{"a":1, "b":2, "c":3}'::jsonb ?| ARRAY['b', 'd'], '["a", "b", "c"]'::jsonb ?& ARRAY['a', 'b'];
SELECT '["a", "b"]'::jsonb || '["a", "d"]'::jsonb, '{"a": "b"}'::jsonb || '{"c": "d"}'::jsonb, '[1, 2]'::jsonb || '3'::jsonb, '{"a": "b"}'::jsonb || '42'::jsonb;
SELECT '{"a": "b", "c": "d"}'::jsonb - 'a', '["a", "b", "c", "b"]'::jsonb - 'b', '["a", "b"]'::jsonb - 1, '["a", {"b":1}]'::jsonb #- '{1,b}';
SELECT json_agg(n), jsonb_agg(n), json_object_agg(k, n), jsonb_object_agg(k, n) FROM (VALUES ('a', 1), ('b', NULL)) v(k, n);
SELECT row_to_json(r), to_jsonb(r) FROM (VALUES (1, 'x')) r(a, b);
SELECT jsonb_agg(r) FROM (VALUES (1, 'x'), (2, 'y')) r(a, b);
SELECT json_agg(r) FROM (VALUES (1, 'x'), (2, 'y')) r(a, b);
SELECT json_agg(n) FROM (VALUES (1)) v(n) WHERE false;
